/* Object type tags (aliased onto the pinned interface ids)            */
/* ================================================================== */
/*
 * NPT_OBJECT_TYPE_* is the runtime's name for the same value that
 * NPT_IFACE_ID_* uses on the wire.  One pinned id per interface; the
 * two macro families coexist so runtime call sites can keep their
 * descriptive names (npt_cs_handle_lookup(..., NPT_OBJECT_TYPE_FOO))
 * while the wire routing uses NPT_IFACE_ID_Foo.
 *
 * Reserved values:
 *   0  INVALID / uninitialized.  npt_context_register_object refuses
 *      to register a handle whose type is 0, so this doubles as the
 *      "don't know, don't register" signal.
 */
#define NPT_OBJECT_TYPE_INVALID  ((npt_object_type)0)

